<form class="form-grid" method="post" action="<?= $workPath ?>/<?= $kind ?>"><?= csrf_field() ?><?php if($groupForm): ?><input type="hidden" name="item_id" value="<?= e($groupForm['id']) ?>"><?php endif; ?><label>Name<input name="name" value="<?= e($groupForm['name']??'') ?>" maxlength="160" required></label><label>Status<select name="status"><?php foreach($statuses as $value=>$label): ?><option value="<?= $value ?>" <?= ($groupForm['status']??'planned')===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><?php if($isCycle): ?><label>Start date<input name="starts_on" type="date" value="<?= e($groupForm['starts_on']??'') ?>"></label><label>End date<input name="ends_on" type="date" value="<?= e($groupForm['ends_on']??'') ?>"></label><?php else: ?><label>Lead<select name="lead_id"><option value="">Not assigned</option><?php foreach($people as $person):if(!$person['active'])continue; ?><option value="<?= e($person['id']) ?>" <?= ($groupForm['lead_id']??'')==$person['id']?'selected':'' ?>><?= e($person['name']) ?></option><?php endforeach; ?></select></label><label>Target date<input name="target_date" type="date" value="<?= e($groupForm['target_date']??'') ?>"></label><?php endif; ?><label class="full">Description<textarea name="description" rows="3" maxlength="5000"><?= e($groupForm['description']??'') ?></textarea></label><div class="full"><button><?= $groupForm?'Save changes':'Create '.ucfirst($kind) ?></button></div></form>
